import{_ as r,c as o,o as n,ae as a}from"./chunks/framework.B8KKhRA6.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"ar/introduction/overview.md","filePath":"ar/introduction/overview.md"}'),s={name:"ar/introduction/overview.md"};function e(i,t,l,g,d,c){return n(),o("div",null,t[0]||(t[0]=[a('<h2 id="نظرة-عامة-على-المشروع" tabindex="-1">نظرة عامة على المشروع <a class="header-anchor" href="#نظرة-عامة-على-المشروع" aria-label="Permalink to &quot;نظرة عامة على المشروع&quot;">​</a></h2><h3 id="بيان-المشكلة" tabindex="-1">بيان المشكلة <a class="header-anchor" href="#بيان-المشكلة" aria-label="Permalink to &quot;بيان المشكلة&quot;">​</a></h3><p>يمكن أن يكون تعلم البرمجة أمراً مربكاً للمبتدئين بسبب الطبيعة المجزأة للموارد، ونقص الممارسة الموجهة، وعدم كفاية الحافز أو حلقات التغذية الراجعة. يواجه العديد من المتعلمين صعوبة في الحفاظ على الثبات والثقة، خاصة عند التنقل بين المفاهيم النظرية والتطبيق العملي. غالباً ما تفشل المنصات التعليمية التقليدية في جعل عملية التعلم جذابة وشخصية.</p><h3 id="نهج-الحل" tabindex="-1">نهج الحل <a class="header-anchor" href="#نهج-الحل" aria-label="Permalink to &quot;نهج الحل&quot;">​</a></h3><p>يهدف مشروعنا إلى تعليم البرمجة باستخدام نهج مستوحى من <strong>دولينجو</strong>—تفكيك مفاهيم البرمجة إلى دروس صغيرة وتفاعلية ودمجها مع عناصر التعلم التفاعلي. ستدعم المنصة مجالات برمجة متنوعة، تغطي <strong>الأساسيات إلى المفاهيم المعيارية</strong>. تدمج عملية التعلم <strong>الشروحات (عبر المقالات أو الفيديوهات)</strong> مع <strong>تمارين البرمجة العملية</strong>، و<strong>حل المشاكل</strong>، و<strong>شرح الكود خطوة بخطوة</strong>، و<strong>تحليل التعقيد</strong>. بالإضافة إلى ذلك، يمكن للمستخدمين <strong>مشاركة حلولهم</strong>، وكسب <strong>الشارات</strong>، والتنافس في لوحات المتصدرين، مما يعزز بيئة تعلم حيوية ومحفزة.</p><h3 id="الميزات-الرئيسية" tabindex="-1">الميزات الرئيسية <a class="header-anchor" href="#الميزات-الرئيسية" aria-label="Permalink to &quot;الميزات الرئيسية&quot;">​</a></h3><ul><li><strong>التعلم التدريجي بأسلوب دولينجو</strong>: الدروس منظمة في شكل مسار مع مستويات ونقاط تحقق.</li><li><strong>محتوى متعدد الأشكال</strong>: كل مفهوم يتضمن شرحاً إما في شكل فيديو أو مقال.</li><li><strong>حل المشاكل المدمج</strong>: مشاكل تطبيقية مع ردود فعل فورية، إجابات نموذجية، وتفصيل كامل للحلول.</li><li><strong>تحليل تعقيد الكود</strong>: كل حل مصحوب بمناقشات الأداء وتحليل التعقيد.</li><li><strong>منهج معياري</strong>: يغطي أساسيات البرمجة بالإضافة إلى وحدات متخصصة (مثل البرمجة كائنية التوجه، الخوارزميات، تطوير الويب).</li><li><strong>التفاعل والمتعة</strong>: شارات، سلاسل متتابعة، ونقاط خبرة للحفاظ على تفاعل المستخدمين.</li><li><strong>مشاركة المجتمع</strong>: يمكن للمستخدمين مشاركة الحلول ومشاهدة مناهج الآخرين لتعزيز التعلم التشاركي.</li><li><strong>الميزة التنافسية</strong>: تحديات برمجة اختيارية ومسابقات مع لوحات متصدرين.</li><li><strong>تتبع التقدم الواضح</strong>: مؤشرات بصرية للدروس المكتملة، والمواضيع المتقنة، والوحدات المعلقة.</li></ul>',7)]))}const u=r(s,[["render",e]]);export{_ as __pageData,u as default};
